### C++ Solution

```cpp
#include <iostream>
#include <vector>
#include <tuple>

using namespace std;

int main()
{
    int b, r, g, c, s, t;
    vector<tuple<int, int, int, int, int, int>> inputs;

    while (cin >> b >> r >> g >> c >> s >> t)
    {
        inputs.push_back(make_tuple(b, r, g, c, s, t));
    }

    // Your code goes here

    return 0;
}
```

### Python Solution

```python
from typing import List, Tuple

inputs: List[Tuple[int, int, int, int, int, int]] = []

while True:
    try:
        b, r, g, c, s, t = map(int, input().split())
        inputs.append((b, r, g, c, s, t))
    except EOFError:
        break

